//同库(博趣中文)：https://m.1bqg.net
//同库(博看小说)：https://m.kchao.net
//同库(希望中文)：https://m.5xw.net
//同库(趣七书屋)：https://m.qu7.net
//同库(洪都中文)：https://m.nchdzx.com
以下代码勿动！
*/

	var bu = "https://" + baseUrl.split("/")[2],
	 c2 = result.match(/c2="([^"]+)/)[1];
  url = result.match(/src="([^"]+)/)[1];
   j = java.ajax(bu + url);
   reg = /function ajax.*\(\)\}/;
   eval(String(j.match(reg)[0]))
   java.ajax(bu + ajax(c2))
   result = java.ajax(baseUrl)

source.exploreUrl:
@js:
var sort = [],
push = (title, link, size) => 
sort.push({
    "title": title,
    "url": link,
    "style": {
      "layout_flexGrow": 1,
      "layout_flexBasisPercent": size
    }
  });

var su = source.key,
url = su + "/menu.html",
html = java.ajax(url),
j = org.jsoup.Jsoup.parse(html),
a = j.select('.divmen a');

Array.from(a, (x, i) => {
	if(i != 0 && i != 4 && i != 5){
		var name = x.text(),
		href = x.attr("href");
		push(name, href, 0.25);
		}
	});

JSON.stringify(sort);

